(()=>{const ROOT='/child-advocacy-site/';const brief={key:'child-protection-network-20261127',date:'2026-11-27T09:00',image:ROOT+'assets/images/daily-child-protection-brief-20261127-network-art.svg',copy:{'zh-Hant':{href:ROOT+'news/child-protection-network-20261127/',small:'每日護童快報｜2026.11.27',title:'通報之後，誰把下一步接起來？',summary:'通報件次不是認定件數；辨識、評估、轉介與後續支持要接得起來。',read:'閱讀快報 →',alt:'現代水墨紙藝：醫療、家庭支持與安全遊戲空間由金線相連，非事件現場'},'zh-Hans':{href:ROOT+'news/child-protection-network-20261127/zh-Hans/',small:'每日护童快报｜2026.11.27',title:'通报之后，谁把下一步接起来？',summary:'通报件次不是认定件数；辨识、评估、转介与后续支持要接得起来。',read:'阅读快报 →',alt:'现代水墨纸艺：医疗、家庭支持与安全游戏空间由金线相连，非事件现场'},en:{href:ROOT+'news/child-protection-network-20261127/en/',small:'DAILY CHILD PROTECTION BRIEF · 27 NOV 2026',title:'After a report: who connects the next step?',summary:'A notification count is not a finding. Assessment, referral and support must stay connected.',read:'Read the brief →',alt:'Contemporary ink-and-paper artwork connecting care, home support and a safe play space; not an incident scene.'},ja:{href:ROOT+'news/child-protection-network-20261127/ja/',small:'毎日子ども保護速報｜2026.11.27',title:'通告の後、次の一歩をつなぐのは誰か',summary:'通告件数は認定件数ではありません。評価、連携、継続支援をつなぎます。',read:'速報を読む →',alt:'医療、家庭支援、安全な遊び場を金の線で結ぶ現代水墨紙作品。事件現場ではありません。'}}};const locale=()=>document.documentElement.lang==='ja'?'ja':document.documentElement.lang==='en'?'en':document.documentElement.lang==='zh-Hans'?'zh-Hans':'zh-Hant';const add=()=>{const slider=document.querySelector('[data-gsap-slider]');if(!slider||slider.querySelector('[data-home-brief="'+brief.key+'"]'))return;const d=brief.copy[locale()],card=document.createElement('a');card.href=d.href;card.dataset.homeArticle='';card.dataset.homeBrief=brief.key;card.dataset.homeDate=brief.date;card.dataset.homePriority='true';card.innerHTML='<img src="'+brief.image+'" alt="'+d.alt+'" data-home-thumb><span class="brief-copy"><small>'+d.small+'</small><h2>'+d.title+'</h2><p>'+d.summary+'</p><span class="brief-read">'+d.read+'</span></span>';const first=[...slider.children].find(el=>el.dataset.homeDate<brief.date);slider.insertBefore(card,first||slider.firstChild);slider.dispatchEvent(new CustomEvent('home:briefs-updated'));};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',add,{once:true});else add();})();